		html: `<p class="eyebrow text-[11px] tracking-[2.4px] font-bold text-muted leading-[1.5] mobile:text-[9px] mobile:tracking-[1.6px]">04 / UN NÚMERO CONOCIDO DE VUELTAS</p><h2>Para un número<br><span>exacto de vueltas.</span></h2><div class="loop-demo grid grid-cols-[1fr_1.15fr] gap-[45px] items-center tablet:gap-[25px] mobile:grid-cols-[1fr] mobile:gap-[23px]"><div><div class="for-parts flex flex-wrap gap-[10px] mb-[24px]">${tag('let i = 0 → inicio')}${tag('i &lt; 3 → condición')}${tag('i++ → paso')}</div><div class="for-state flex items-center gap-[35px] mb-[22px] [&_b]:block [&_b]:text-[40px] [&_b]:text-blue [&_span]:text-[11px] [&_span]:text-muted mobile:gap-[22px]"><div><span>VARIABLE i</span><b id="for-i">0</b></div><div><span>CONDICIÓN i &lt; 3</span><b id="for-condition">true</b></div></div><div class="cups-row flex gap-[10px] min-h-[40px] text-[26px] mb-[22px]" id="for-cups" aria-hidden="true"></div><div class="flex items-center gap-[16px] flex-wrap mb-[18px]"><button class="primary inline-flex items-center justify-between gap-[30px] rounded-[4px] text-[14px] bg-ink text-[#fff] py-[16px] px-[21px] border-[0] border-none border-[currentColor] [&:hover]:bg-blue" data-action="for-step">Servir una taza <span>+</span></button><button class="text-button [background:none] text-[12px] py-[10px] px-0 border-[0] border-none border-[currentColor] [&_span]:ml-[12px]" data-action="for-reset">Reiniciar</button></div><p class="feedback text-[14px] min-h-[23px] text-blue [&.success]:text-[#286247] [&.incorrect]:text-[#9e4f24]" id="for-feedback" aria-live="polite">Hacé clic para correr una vuelta del bucle.</p></div><div class="code-panel [background:#23364b] text-[#e8edf3] rounded-[7px] min-w-0 py-[24px] px-[30px] tablet:p-[22px] mobile:p-[20px] mobile:[&_pre]:text-[13px]"><span class="code-label block text-[9px] tracking-[1.6px] text-[#a6b8c8] mb-[18px]">JAVASCRIPT</span>${code('<em>for</em> (<em>let</em> i = <b>0</b>; i < <b>3</b>; i++) {\n  servirTaza();\n}')}</div></div>`,
